partial def Code.mapFVarM [MonadLiftT CompilerM m] [Monad m] (f : FVarId → m FVarId) (c : Code) : m Code := do
  match c with
  | .let decl k =>
    let decl ← LetDecl.mapFVarM f decl
    return Code.updateLet! c decl (← mapFVarM f k)
  | .fun decl k =>
    let params ← decl.params.mapM (Param.mapFVarM f)
    let decl ← decl.update (← Expr.mapFVarM f decl.type) params (← mapFVarM f decl.value)
    return Code.updateFun! c decl (← mapFVarM f k)
  | .jp decl k =>
    let params ← decl.params.mapM (Param.mapFVarM f)
    let decl ← decl.update (← Expr.mapFVarM f decl.type) params (← mapFVarM f decl.value)
    return Code.updateFun! c decl (← mapFVarM f k)
  | .cases cs =>
    return Code.updateCases! c (← Expr.mapFVarM f cs.resultType) (← f cs.discr) (← cs.alts.mapM (·.mapCodeM (mapFVarM f)))
  | .jmp fn args =>
    return Code.updateJmp! c (← f fn) (← args.mapM (Arg.mapFVarM f))
  | .return var =>
    return Code.updateReturn! c (← f var)
  | .unreach typ =>
    return Code.updateUnreach! c (← Expr.mapFVarM f typ)

def Decl.cse (decl : Decl) : CompilerM Decl := do
  let value ← decl.value.cse
  return { decl with value }

def Decl.elimDeadBranches (decls : Array Decl) : CompilerM (Array Decl) := do
  let mut assignments := decls.map fun _ => {}
  let initialVal i :=

    if decls[i]!.safe then .bot else .top
  let mut funVals := decls.size.fold (init := .empty) fun i p => p.push (initialVal i)
  let ctx := { decls }
  let mut state := { assignments, funVals }
  (_, state) ← inferMain |>.run ctx |>.run state
  funVals := state.funVals
  assignments := state.assignments
  modifyEnv fun e =>
    decls.size.fold (init := e) fun i env =>
      addFunctionSummary env decls[i]!.name funVals[i]!

  decls.mapIdxM fun i decl => if decl.safe then elimDead assignments[i]! decl else return decl

