  mvar.mvarId!.assign e
  pure stx

partial def ofString (s : String) : FileMap :=
  let rec loop (i : String.Pos) (line : Nat) (ps : Array String.Pos) : FileMap :=
    if s.atEnd i then { source := s, positions := ps.push i }
    else
      let c := s.get i
      let i := s.next i
      if c == '\n' then loop i (line+1) (ps.push i)
      else loop i line ps
  loop 0 1 (#[0])

partial def toPosition (fmap : FileMap) (pos : String.Pos) : Position :=
  match fmap with
  | { source := str, positions := ps } =>
    if ps.size >= 2 && pos <= ps.back then
      let rec toColumn (i : String.Pos) (c : Nat) : Nat :=
        if i == pos || str.atEnd i then c
        else toColumn (str.next i) (c+1)
      let rec loop (b e : Nat) :=
        let posB := ps[b]!
        if e == b + 1 then { line := fmap.getLine b, column := toColumn posB 0 }
        else
          let m := (b + e) / 2;
          let posM := ps.get! m;
          if pos == posM then { line := fmap.getLine m, column := 0 }
          else if pos > posM then loop m e
          else loop b m
      loop 0 (ps.size -1)
    else if ps.isEmpty then
      ⟨0, 0⟩
    else
      ⟨fmap.getLastLine, (pos - ps.back).byteIdx⟩

def Profile.collide (ps : Array Profile) : Option Profile := do
  let base ← ps[0]?
  let thread := Thread.new "collided"
  let thread := ps.map (·.threads) |>.flatten.foldl collideThreads { thread with }
  return { base with threads := #[thread.toThread] }

def Profile.export (name : String) (startTime : Milliseconds) (traceState : TraceState)
    (opts : Options) : IO Profile := do
  let thread := Thread.new name
  let trace := .trace {
    cls := `runFrontend, startTime, stopTime := (← IO.monoNanosNow).toFloat / 1000000000,
    collapsed := true } "" (traceState.traces.toArray.map (·.msg))
  let thread ← addTrace (Lean.trace.profiler.output.pp.get opts) { thread with } trace
  return {
    meta := { startTime, categories }
    threads := #[thread.toThread]
  }

def Thread.new (name : String) : Thread := {
