  samples := { stack := #[], time := #[], weight := #[], length := 0 }
  stackTable := { frame := #[], «prefix» := #[], category := #[], subcategory := #[], length := 0 }
  frameTable := { func := #[], length := 0 }
  stringArray := #[]
  funcTable := {
